const localDay=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const defaultState=()=>({xp:0,gems:0,streak:0,lastDay:'',hearts:5,heartAt:Date.now(),completed:[],unitRewards:[],knownWords:[],correct:0,answered:0,lessonsDone:0,perfect:0,reviewed:0,achievements:[],cosmetics:[],equipped:'default',questDay:localDay(),questLessons:0,questCorrect:0,questXP:0,questRewarded:false});
let state=loadState();let currentLesson=null;let currentQuestions=[];let questionIndex=0;let lessonCorrect=0;let missedQuestions=new Set();let selected=null;let chosenTiles=[];let matchSelected=null;let matchPairs=[];let currentView='learn';let quickMode=false;let toastTimer;
function loadState(){try{return {...defaultState(),...JSON.parse(localStorage.getItem('bok-progress')||'{}')}}catch{return defaultState()}}
function save(){try{localStorage.setItem('bok-progress',JSON.stringify(state))}catch{}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function phoneticWord(word){const tokens=String(word).toLocaleLowerCase('hr-HR').match(/dž|lj|nj|[a-zčćđšž]/g)||[String(word)];const vowels=new Set(['a','e','i','o','u']);const syllables=[];let current=[],hasVowel=false;for(const token of tokens){if(vowels.has(token)){if(hasVowel){let onset=[];if(current.length&&!vowels.has(current[current.length-1]))onset=[current.pop()];syllables.push(current.join(''));current=onset;hasVowel=false}current.push(token);hasVowel=true}else current.push(token)}if(current.length)syllables.push(current.join(''));const sounds={dž:'j',lj:'ly',nj:'ny',č:'ch',ć:"ch'",đ:"j'",š:'sh',ž:'zh',j:'y',c:'ts',a:'ah',e:'eh',i:'ee',o:'oh',u:'oo'};return syllables.map(syllable=>syllable.replace(/dž|lj|nj|[a-zčćđšž]/g,letter=>sounds[letter]||letter)).filter(Boolean).join('-')}
function phoneticText(text){return String(text).replace(/[A-Za-zČĆĐŠŽčćđšž]+/g,word=>phoneticWord(word))}
function pronunciationGuide(text){return `<div class="pronunciation-guide"><span>Say it aloud</span><b>${esc(phoneticText(text))}</b><small>Approximate English sounds · stress is not marked</small></div>`}
function soundKey(){return `<details class="sound-key"><summary>Croatian sound key</summary><p>č = ch as in “church”; ć = softer ch (shown as ch'); đ = soft j (shown as j'); dž = j as in “jam”; š = sh; ž = the sound in “vision”; j = y; c = ts. Vowels stay pure and short: a = ah, e = eh, i = ee, o = oh, u = oo. A hyphen separates rough syllables. These English spellings are approximate and do not mark stress.</p></details>`}
function allLessons(){return COURSES.flatMap(c=>c.units.flatMap(u=>u.lessons.map((title,i)=>({id:`${c.id}-${u.id}-${i}`,section:c,unit:u,title,index:i,unitIndex:c.units.indexOf(u)}))))}
function unlocked(item){const all=allLessons(),i=all.findIndex(x=>x.id===item.id);return i===0||state.completed.includes(all[i-1].id)}
function sectionUnlocked(section){if(section===COURSES[0])return true;const i=COURSES.indexOf(section),prev=COURSES[i-1];return prev.units.every(u=>u.lessons.every((_,j)=>state.completed.includes(`${prev.id}-${u.id}-${j}`)))}
function makeQuestions(item){
  const pack=PACKS[item.unit.pack],sequence=LESSON_SEQUENCES[item.unit.pack]?.[item.index];
  if(!sequence)return [];
  const orderedLessons=allLessons();
  const lessonPosition=orderedLessons.findIndex(lesson=>lesson.id===item.id);
  const coursePlans=orderedLessons.slice(0,lessonPosition+1).map(lesson=>LESSON_SEQUENCES[lesson.unit.pack]?.[lesson.index]).filter(Boolean);
  const unitPlans=LESSON_SEQUENCES[item.unit.pack]||[];
  const lessonWords=coursePlans.flatMap(plan=>plan.words);
  const word=sequence.words[item.index%sequence.words.length];
  const phrase=sequence.phrase;
  const optionsFor=(answer,candidates)=>{
    const distinct=[...new Map(candidates.filter(value=>value&&choiceKey(value)!==choiceKey(answer)).map(value=>[choiceKey(value),value])).values()];
    return shuffle([...shuffle(distinct).slice(0,2),answer]);
  };
  const meaningOptions=optionsFor(sequence.meaning,[...coursePlans.map(plan=>plan.meaning),...unitPlans.map(plan=>plan.meaning),pack.read[3],...pack.words.map(pair=>pair[1])]);
  const englishOptions=optionsFor(word[1],[...lessonWords.map(pair=>pair[1]),...pack.words.map(pair=>pair[1])]);
  const token=sequence.words.find(pair=>phrase.toLocaleLowerCase('hr-HR').includes(pair[0].toLocaleLowerCase('hr-HR'))) || [phrase.match(/^[^\s,;:.!?]+/)?.[0]||sequence.words[0][0],sequence.words[0][1]];
  const tokenPattern=new RegExp(token[0].replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');
  const fillAnswer=phrase.match(tokenPattern)?.[0]||token[0];
  const blankPhrase=phrase.replace(tokenPattern,'___');
  const fillOptions=optionsFor(fillAnswer,[...lessonWords.map(pair=>pair[0]),...pack.words.map(pair=>pair[0])]);
  const ruleOptions=optionsFor(sequence.note,[...coursePlans.map(plan=>plan.note),...unitPlans.map(plan=>plan.note),pack.grammar[3]]);
  const situationOptions=optionsFor(sequence.scenario,[...coursePlans.map(plan=>plan.scenario),...unitPlans.map(plan=>plan.scenario)]);
  const questions=[
    {type:'choice',title:'Learn a useful word',prompt:`What does “${word[0]}” mean?`,pronunciation:word[0],feedbackPronunciation:word[0],options:englishOptions,answer:word[1],explain:`“${word[0]}” means “${word[1]}”. ${sequence.note}`},
    {type:'translate',title:'Understand the phrase',prompt:`What does “${phrase}” mean?`,pronunciation:phrase,feedbackPronunciation:phrase,options:meaningOptions,answer:sequence.meaning,explain:`Use this when ${sequence.scenario.toLowerCase()} ${sequence.note}`},
    {type:'build',title:'Build the phrase',prompt:`Put the words in order to say: “${sequence.meaning}”`,feedbackPronunciation:phrase,answer:phrase,tiles:shuffle((phrase.match(/\S+/g)||[phrase])),explain:`“${phrase}” means “${sequence.meaning}”. ${sequence.note}`},
    {type:'fill',title:'Complete the phrase',prompt:`Complete the Croatian for this situation: ${sequence.scenario} “${blankPhrase}”`,pronunciation:blankPhrase,feedbackPronunciation:phrase,options:fillOptions,answer:fillAnswer,explain:`The missing word is “${fillAnswer}” (${token[1]}). The full phrase means “${sequence.meaning}”. ${sequence.note}`},
    {type:'match',title:'Connect the words',prompt:'Match each Croatian word with its English meaning.',feedbackPronunciation:sequence.words.map(pair=>pair[0]).join(' · '),pairs:sequence.words.map(pair=>({a:pair[0],b:pair[1]})),explain:`These words are useful when ${sequence.scenario.toLowerCase()}`,detail:sequence.words.map(pair=>`${pair[0]} = ${pair[1]}`).join('  ·  ')},
    {type:'grammar',title:'Notice the pattern',prompt:`Which language point helps you use “${phrase}” correctly?`,pronunciation:phrase,feedbackPronunciation:phrase,options:ruleOptions,answer:sequence.note,explain:sequence.note},
    {type:'read',title:'Use it in context',prompt:`When would you use “${phrase}”?`,pronunciation:phrase,feedbackPronunciation:phrase,options:situationOptions,answer:sequence.scenario,explain:`“${phrase}” means “${sequence.meaning}”. ${sequence.note}`}
  ];
  questions.forEach(question=>{
    if(question.options&&!question.options.some(option=>choiceKey(option)===choiceKey(question.answer)))question.options=optionsFor(question.answer,question.options);
  });
  return questions;
}
function updateStats(){if(state.questDay!==localDay()){state.questDay=localDay();state.questLessons=0;state.questCorrect=0;state.questXP=0;state.questRewarded=false;save()}if(state.hearts<5){const healed=Math.floor((Date.now()-state.heartAt)/1800000);if(healed>0){state.hearts=Math.min(5,state.hearts+healed);state.heartAt+=healed*1800000;save()}}document.getElementById('streak').textContent=state.streak;document.getElementById('hearts').textContent=state.hearts;document.getElementById('gems').textContent=state.gems;document.getElementById('badge-count').textContent=state.achievements.length;document.getElementById('profile-level').textContent=`${levelInfo().name} · ${levelInfo().level}`;const looks={sea:['#d7efff','#2676b9'],coral:['#ffe5df','#d96257'],sun:['#fff0c6','#bb871c'],star:['#eee8ff','#785dc0']};document.querySelectorAll('.top-avatar,.avatar,.profile-large').forEach(el=>{if(state.equipped==='star'){el.textContent='⭐'}else el.textContent='M';const look=looks[state.equipped];if(look){el.style.background=look[0];el.style.color=look[1]}else{el.style.background='';el.style.color=''}})}
function levelInfo(){let level=1,remaining=state.xp;while(remaining>=level*100){remaining-=level*100;level++}const label=level<4?'A1':level<8?'A2':level<13?'B1':level<19?'B2':'C1';return {level,name:level<=3?'Beginner':level<=7?'Elementary':level<=12?'Intermediate':level<=18?'Upper intermediate':'Advanced',label,within:remaining,need:level*100}}
function renderPath(){const root=document.getElementById('view-root');root.innerHTML=`<div class="welcome"><div><div class="eyebrow"><span class="flag">🇭🇷</span> YOUR CROATIAN COURSE</div><h1>Let’s make a little progress<span class="dot">.</span></h1><p>Pick up where you left off. Your next lesson is waiting.</p></div><div class="xp-card"><div class="xp-head"><span>LEVEL ${levelInfo().level} · ${levelInfo().label}</span><b>✦ ${state.xp} XP</b></div><div class="xp-bar"><i style="width:${levelInfo().within/levelInfo().need*100}%"></i></div><small>${levelInfo().need-levelInfo().within} XP to level ${levelInfo().level+1}</small></div></div>
    ${questsMarkup()}<div class="path-heading"><div><span class="eyebrow">YOUR LEARNING PATH</span><h2>One step at a time</h2></div><span class="path-stats">${state.completed.length} lessons complete <i>·</i> ${allLessons().length} in your course</span></div><div class="course-path">${COURSES.map((c,ci)=>courseMarkup(c,ci)).join('')}</div>`;
  root.querySelectorAll('[data-lesson]').forEach(btn=>btn.addEventListener('click',()=>{const item=allLessons().find(x=>x.id===btn.dataset.lesson);if(item&&unlocked(item))startLesson(item)}));root.querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',()=>navigate('practice')));updateStats();}
function questsMarkup(){const quests=[['Complete 3 lessons',state.questLessons,3,'lesson'],['Earn 50 XP',state.questXP,50,'xp'],['Answer 10 correctly',state.questCorrect,10,'correct']];return `<section class="quests"><div class="quest-heading"><div><span class="eyebrow">TODAY’S QUESTS</span><b>Little goals, lovely rewards</b></div><span class="quest-reward">${state.questRewarded?'✓ Reward collected':'✦ +15 gems'}</span></div><div class="quest-list">${quests.map(([name,n,max,type])=>`<div class="quest"><span class="quest-check ${n>=max?'complete':''}">${n>=max?'✓':'○'}</span><span class="quest-name">${name}</span><span class="quest-bar"><i style="width:${Math.min(100,n/max*100)}%"></i></span><small>${Math.min(n,max)}/${max}</small></div>`).join('')}</div></section>`}
function courseMarkup(course,ci){const open=sectionUnlocked(course);const done=course.units.flatMap(u=>u.lessons).filter((_,i)=>false).length;const ids=course.units.flatMap(u=>u.lessons.map((_,j)=>`${course.id}-${u.id}-${j}`));const completed=ids.filter(id=>state.completed.includes(id)).length;return `<section class="course-section ${course.color} ${open?'':'section-locked'}"><div class="section-banner"><div class="section-icon">${['🌊','🪴','🍋','🌅','🧿','⚓'][ci]}</div><div class="section-copy"><span>${esc(course.label)}</span><h3>${esc(['First steps','Everyday Croatian','Explore more','Tell your story','Use natural Croatian','Advanced fluency'][ci])}</h3><small>${completed} / ${ids.length} lessons · ${open?'Continue your journey':'Complete the previous section to unlock'}</small></div><div class="section-level">${course.level}</div></div><div class="unit-list">${course.units.map((u,ui)=>unitMarkup(course,u,ui,open)).join('')}</div></section>`}
function unitMarkup(course,unit,ui,sectionOpen){const lessonObjs=unit.lessons.map((title,i)=>({id:`${course.id}-${unit.id}-${i}`,title}));return `<article class="unit-card"><div class="unit-top"><span class="unit-icon">${unit.icon}</span><div><span class="unit-kicker">UNIT ${String(ui+1).padStart(2,'0')}</span><b>${esc(unit.title)}</b><small>${esc(unit.theme)}</small></div><span class="unit-progress">${lessonObjs.filter(x=>state.completed.includes(x.id)).length}/${lessonObjs.length}</span></div><div class="nodes">${lessonObjs.map((lesson,i)=>{const item=allLessons().find(x=>x.id===lesson.id);const done=state.completed.includes(lesson.id),open=sectionOpen&&unlocked(item);const current=open&&!done;return `<button class="lesson-node ${done?'done':''} ${current?'current':''} ${open?'':'locked'}" data-lesson="${lesson.id}" ${open?'':'disabled'} aria-label="${done?'Review':current?'Start':'Locked'} ${esc(lesson.title)}"><span>${done?'✓':open?'★':'🔒'}</span><small>${esc(lesson.title)}</small></button>`}).join('')}<span class="milestone ${lessonObjs.every(x=>state.completed.includes(x.id))?'earned':''}" title="Unit milestone reward">${lessonObjs.every(x=>state.completed.includes(x.id))?'🎁':'✦'}</span></div></article>`}
function navigate(view){currentView=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('crumb').innerHTML=`My path <span>›</span> <b>${({learn:'Learn Croatian',practice:'Practice',achievements:'Achievements',league:'Weekly league',profile:'My profile'})[view]||view}</b>`;const root=document.getElementById('view-root');if(view==='learn')renderPath();if(view==='practice')renderPractice(root);if(view==='achievements')renderAchievements(root);if(view==='league')renderLeague(root);if(view==='profile')renderProfile(root);window.scrollTo({top:0,behavior:'smooth'})}
function renderPractice(root){const review=PACKS.hello.words.concat(PACKS.meet.words,PACKS.cafe.words).slice(0,12);root.innerHTML=`<div class="page-intro"><span class="eyebrow">A FEW MINUTES FOR YOU</span><h1>Practice makes progress<span class="dot">.</span></h1><p>Review familiar words, recover a heart, or try a quick challenge.</p></div><div class="practice-cards"><button class="practice-action" id="flashcards"><span class="action-emoji">🃏</span><b>Word flashcards</b><small>Review ${Math.max(5,state.knownWords.length)} words</small><span class="action-arrow">→</span></button><button class="practice-action" id="heart-recover"><span class="action-emoji">💗</span><b>Heart practice</b><small>Answer 3 correctly to earn a heart</small><span class="action-arrow">→</span></button><button class="practice-action" id="quick-lesson"><span class="action-emoji">⚡</span><b>Quick challenge</b><small>A 3-question daily boost</small><span class="action-arrow">→</span></button></div><section class="review-panel"><div class="panel-title"><div><span class="eyebrow">SPACED REPETITION</span><h2>Your word garden</h2></div><span class="tag-count">${state.knownWords.length} learned</span></div><div class="word-garden">${(state.knownWords.length?state.knownWords:review.map(x=>x[0])).map((hr,i)=>`<div class="garden-word"><b>${esc(hr)}</b><small class="garden-phonetic">${esc(phoneticText(hr))}</small><small>${esc(findTranslation(hr)||'Tap to revisit')}</small></div>`).join('')}</div></section>`;
  root.querySelector('#flashcards').onclick=()=>startFlashcard();root.querySelector('#heart-recover').onclick=()=>startHeartPractice();root.querySelector('#quick-lesson').onclick=()=>startQuickChallenge();}
function findTranslation(hr){for(const p of Object.values(PACKS)){const v=p.words.find(x=>x[0]===hr);if(v)return v[1]}for(const sequence of Object.values(LESSON_SEQUENCES).flat()){const v=sequence.words.find(x=>x[0]===hr);if(v)return v[1]}return ''}
function renderAchievements(root){const list=[['🌱','First steps','Complete your first lesson',state.lessonsDone>=1],['💯','Perfect!','Finish a lesson with every answer correct',state.perfect>=1],['📚','Word collector','Learn 100 new words',state.knownWords.length>=100],['🏝️','Unit explorer','Complete all lessons in a unit',COURSES.some(c=>c.units.some(u=>u.lessons.every((_,i)=>state.completed.includes(`${c.id}-${u.id}-${i}`))))],['🔥','Week of words','Practice 7 days in a row',state.streak>=7],['🗓️','One month strong','Practice 30 days in a row',state.streak>=30],['✨','Word wonder','Learn 1,000 new words',state.knownWords.length>=1000],['🏆','Section star','Complete a full proficiency section',COURSES.some(c=>c.units.every(u=>u.lessons.every((_,i)=>state.completed.includes(`${c.id}-${u.id}-${i}`))))]];root.innerHTML=`<div class="page-intro"><span class="eyebrow">YOUR LITTLE VICTORIES</span><h1>Achievements<span class="dot">.</span></h1><p>Every step is worth celebrating.</p></div><div class="achievement-grid">${list.map(([icon,title,desc,earned])=>`<article class="achievement ${earned?'earned':''}"><span class="badge-icon">${icon}</span><div><b>${title}</b><small>${desc}</small></div><span class="badge-state">${earned?'EARNED':'LOCKED'}</span></article>`).join('')}</div>`}
function renderLeague(root){const people=[['Lana','🦊',310],['Filip','🐬',260],['Nina','🦉',190],['Maja','🐻',145],['Ivan','🦝',105],['Petra','🐝',80]];const list=[...people,['You','🙂',state.xp%500]].sort((a,b)=>b[2]-a[2]);root.innerHTML=`<div class="page-intro"><span class="eyebrow">WEEKLY LEAGUE · OFFLINE PREVIEW</span><h1>A little friendly focus<span class="dot">.</span></h1><p>These are simulated learners for this offline prototype. Your weekly XP moves you up the table.</p></div><div class="league-card"><div class="league-header"><span>🏅</span><div><b>Coral league</b><small>Resets Monday · Top 3 move up</small></div><span class="league-days">${7-new Date().getDay()} days left</span></div>${list.map(([name,animal,xp],i)=>`<div class="league-row ${name==='You'?'you':''}"><span class="rank">${i+1}</span><span class="league-animal">${animal}</span><b>${name}${name==='You'?' (you)':''}</b><span>${xp} XP</span></div>`).join('')}</div>`}
function renderProfile(root){const shop=[['sea','🌊','Adriatic blue',20],['coral','🪸','Dalmatian coral',25],['sun','☀️','Golden sunshine',30],['star','⭐','Little star badge',35]];root.innerHTML=`<div class="page-intro"><span class="eyebrow">YOUR LEARNING, YOUR PACE</span><h1>My profile<span class="dot">.</span></h1><p>Your progress stays on this browser.</p></div><section class="profile-panel"><div class="profile-hero"><span class="profile-large">M</span><div><h2>Croatian learner</h2><span>${levelInfo().name} · ${levelInfo().label}</span></div></div><div class="profile-metrics"><div><b>${levelInfo().level}</b><small>Player level</small></div><div><b>${state.xp}</b><small>Total XP</small></div><div><b>${state.lessonsDone}</b><small>Lessons complete</small></div><div><b>${state.knownWords.length}</b><small>Words learned</small></div></div><div class="profile-progress"><div class="xp-head"><span>LEVEL ${levelInfo().level} PROGRESS</span><b>${levelInfo().within}/${levelInfo().need} XP</b></div><div class="xp-bar"><i style="width:${levelInfo().within/levelInfo().need*100}%"></i></div></div><p class="local-note">🔒 Progress is saved locally in this browser. No account or internet connection is needed to learn.</p></section><section class="shop-panel"><div class="panel-title"><div><span class="eyebrow">EARNED WITH YOUR LEARNING</span><h2>Little gem shop</h2></div><span class="quest-reward">✦ ${state.gems} gems</span></div><p class="shop-description">Spend your learning gems on small profile treats. Everything here is optional.</p><div class="shop-items">${shop.map(([id,icon,name,cost])=>{const owned=state.cosmetics.includes(id),equipped=state.equipped===id;return `<article class="shop-item"><span class="shop-item-icon ${id}">${icon}</span><div><b>${name}</b><small>${owned?(equipped?'Equipped':'Owned'):`${cost} gems`}</small></div><button data-buy="${id}" ${!owned&&state.gems<cost?'disabled':''}>${equipped?'On':owned?'Wear':`Buy · ${cost} ✦`}</button></article>`}).join('')}</div></section>`;root.querySelectorAll('[data-buy]').forEach(button=>button.onclick=()=>{const item=shop.find(x=>x[0]===button.dataset.buy),owned=state.cosmetics.includes(item[0]);if(!owned){if(state.gems<item[3])return toast('Earn a few more gems by learning!');state.gems-=item[3];state.cosmetics.push(item[0])}state.equipped=item[0];save();renderProfile(root);updateStats();toast(owned?'Look updated!':`${item[2]} unlocked!`) });updateStats()}

function startLesson(item){if(!unlocked(item))return;quickMode=false;currentLesson=item;currentQuestions=makeQuestions(item);questionIndex=0;lessonCorrect=0;missedQuestions=new Set();renderQuestion()}
function renderQuestion(){selected=null;chosenTiles=[];matchSelected=null;matchPairs=[];const q=currentQuestions[questionIndex],total=currentQuestions.length;const root=document.getElementById('lesson-root');root.innerHTML=`<div class="lesson-screen"><header class="lesson-top"><button class="close-lesson" id="close-lesson" aria-label="Close lesson">×</button><div class="lesson-progress"><div><i style="width:${questionIndex/total*100}%"></i></div><span>${questionIndex+1} / ${total}</span></div><div class="lesson-hearts">${'♥'.repeat(state.hearts)}<span>${'♡'.repeat(5-state.hearts)}</span></div></header><div class="question-area"><div class="exercise-label">${esc(currentLesson.unit.title)} <span>·</span> ${esc(q.title)}</div>${soundKey()}${q.passage?`<div class="reading-passage">${esc(q.passage)}</div>`:''}<h2>${esc(q.prompt)}</h2>${q.pronunciation?pronunciationGuide(q.pronunciation):''}<div id="question-body">${questionBody(q)}</div><div id="feedback" class="feedback"></div></div><footer class="lesson-footer"><div id="lesson-hint">${q.type==='match'?'Match every pair to continue.':q.type==='build'?'Tap the words in the order you want.':'Choose an answer, then check it.'}</div><button id="check-answer" class="check-button" disabled>${q.type==='match'?'Continue':'Check'}</button></footer></div>`;
  document.getElementById('close-lesson').onclick=()=>{document.getElementById('lesson-root').innerHTML='';navigate('learn')};wireQuestion(q);}
function questionBody(q){if(['choice','translate','fill','grammar','read'].includes(q.type)){const options=q.options.map((o,i)=>`<button class="answer-option" data-choice="${i}"><span>${esc(o)}</span>${q.type==='fill'?`<small>${esc(phoneticText(o))}</small>`:''}</button>`).join('');return `<div class="answer-options">${options}</div>`}
   if(q.type==='build')return `<div class="tile-answer" id="tile-answer"></div><div class="tile-bank">${shuffle(q.tiles).map((word,i)=>`<button class="word-tile" data-tile="${i}"><span>${esc(word)}</span><small>${esc(phoneticText(word))}</small></button>`).join('')}</div>`;
   if(q.type==='match')return `<div class="match-grid"><div>${shuffle(q.pairs.map((x,i)=>({...x,id:i}))).map(x=>`<button class="match-option" data-side="a" data-id="${x.id}"><span>${esc(x.a)}</span><small>${esc(phoneticText(x.a))}</small></button>`).join('')}</div><div>${shuffle(q.pairs.map((x,i)=>({...x,id:i}))).map(x=>`<button class="match-option" data-side="b" data-id="${x.id}">${esc(x.b)}</button>`).join('')}</div></div>`;
  return '';}
function shuffle(arr){return [...arr].sort(()=>Math.random()-.5)}
 function wireQuestion(q){const body=document.getElementById('question-body'),check=document.getElementById('check-answer');body.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{body.querySelectorAll('.answer-option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selected=q.options[Number(b.dataset.choice)];check.disabled=false});
  if(q.type==='build'){const tiles=[...body.querySelectorAll('[data-tile]')];const repaint=()=>{document.getElementById('tile-answer').innerHTML=chosenTiles.map((x,i)=>`<button class="word-tile picked" data-picked="${i}"><span>${esc(x)}</span><small>${esc(phoneticText(x))}</small></button>`).join('');body.querySelectorAll('[data-picked]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.picked);tiles.find(t=>t.querySelector('span').textContent===chosenTiles[i]&&!t.disabled)?.removeAttribute('disabled');chosenTiles.splice(i,1);repaint();check.disabled=chosenTiles.length===0})};tiles.forEach(t=>t.onclick=()=>{if(t.disabled)return;t.disabled=true;chosenTiles.push(t.querySelector('span').textContent);repaint();check.disabled=false})}
 if(q.type==='match'){const complete=()=>{check.disabled=matchPairs.length<q.pairs.length};body.querySelectorAll('.match-option').forEach(b=>b.onclick=()=>{if(b.classList.contains('matched'))return;if(!matchSelected){matchSelected=b;b.classList.add('selected');return}if(b.dataset.side===matchSelected.dataset.side){matchSelected.classList.remove('selected');matchSelected=b;b.classList.add('selected');return}const previous=matchSelected,same=b.dataset.id===previous.dataset.id;if(same){b.classList.add('matched');previous.classList.add('matched');matchPairs.push(b.dataset.id)}else{b.classList.add('wrong');previous.classList.add('wrong');setTimeout(()=>{b.classList.remove('wrong');previous.classList.remove('wrong','selected')},450)}matchSelected=null;complete()})}
 check.onclick=()=>checkQuestion(q);}
function choiceKey(s){return String(s).toLocaleLowerCase('hr-HR').replace(/[.!?,;:]/g,'').replace(/\s+/g,' ').trim()}
function pronunciationFeedback(q){return q.feedbackPronunciation?`<span class="feedback-pronunciation">Try saying: <b>${esc(phoneticText(q.feedbackPronunciation))}</b></span>`:''}
function checkQuestion(q){const feedback=document.getElementById('feedback'),check=document.getElementById('check-answer'),body=document.getElementById('question-body');const given=q.type==='build'?chosenTiles.join(' ').trim():selected;const correct=q.type==='match'?matchPairs.length===q.pairs.length:choiceKey(given)===choiceKey(q.answer);const answerText=q.type==='match'?'Every pair is matched':q.answer;
  state.answered++;state.questCorrect+=correct?1:0;if(correct){if(!missedQuestions.has(questionIndex))lessonCorrect++;state.correct++;state.xp+=2;state.questXP+=2;feedback.className='feedback good';feedback.innerHTML=`<b>✓ ${q.type==='build'?'Great sentence!':missedQuestions.has(questionIndex)?'Correct after retry!':'Odlično! That’s right.'}</b><strong class="feedback-answer">${esc(answerText)}</strong>${pronunciationFeedback(q)}<span>${esc(q.explain)}</span>`;if(questionIndex===0){const hr=LESSON_SEQUENCES[currentLesson.unit.pack]?.[currentLesson.index]?.words?.[0]?.[0];if(hr&&!state.knownWords.includes(hr))state.knownWords.push(hr)}}else{if(!missedQuestions.has(questionIndex)){missedQuestions.add(questionIndex);state.hearts=Math.max(0,state.hearts-1);state.heartAt=Date.now()}const received=given?`You selected “${given}.” `:'You did not select an answer. ';const reason=q.type==='build'?`The word order you built does not match the target phrase. ${q.explain}`:`${received}The correct answer is “${answerText}”. ${q.explain}`;feedback.className='feedback bad';feedback.innerHTML=`<b>Not quite — here’s the difference.</b><strong class="feedback-answer">Correct answer: ${esc(answerText)}</strong>${pronunciationFeedback(q)}<span>${esc(reason)}</span>`;if(state.hearts===0)feedback.innerHTML+=`<span class="heart-softener">You can keep learning. Hearts return over time, or use heart practice.</span>`;body.querySelectorAll('button').forEach(button=>button.disabled=true);checkQuestReward();save();updateStats();check.textContent='Try again';check.disabled=false;check.onclick=()=>renderQuestion();return}
 checkQuestReward();save();updateStats();body.querySelectorAll('button').forEach(button=>button.disabled=true);check.disabled=false;check.textContent=questionIndex===currentQuestions.length-1?'See results':'Continue';check.onclick=()=>{questionIndex++;if(questionIndex>=currentQuestions.length)finishLesson();else renderQuestion()};}
function checkQuestReward(){if(!state.questRewarded&&state.questLessons>=3&&state.questXP>=50&&state.questCorrect>=10){state.questRewarded=true;state.gems+=15;toast('Daily quests complete! +15 gems')}}
function finishLesson(){const accuracy=Math.round(lessonCorrect/currentQuestions.length*100),perfect=accuracy===100,root=document.getElementById('lesson-root');if(quickMode){quickMode=false;const reward=lessonCorrect*3;state.xp+=reward;state.questXP+=reward;checkQuestReward();save();updateStats();root.innerHTML=`<div class="lesson-screen result-screen"><div class="result-medal">⚡</div><span class="eyebrow">QUICK CHALLENGE COMPLETE</span><h1>Nice little boost!</h1><p>You got ${lessonCorrect} of ${currentQuestions.length} right.</p><div class="result-stats"><div><b>+${reward}</b><small>Bonus XP</small></div><div><b>${accuracy}%</b><small>Accuracy</small></div><div><b>🔥 ${state.streak}</b><small>Day streak</small></div><div><b>♥ ${state.hearts}</b><small>Hearts</small></div></div><button class="primary-result result-full" id="quick-done">Back to practice</button></div>`;document.getElementById('quick-done').onclick=()=>{root.innerHTML='';navigate('practice')};return}const isNew=!state.completed.includes(currentLesson.id);let reward=20+(perfect?15:0);let gemsEarned=5+(perfect?3:0);state.xp+=reward;state.questXP+=reward;state.gems+=gemsEarned;state.lessonsDone+=isNew?1:0;state.perfect+=perfect?1:0;state.questLessons+=isNew?1:0;const today=localDay();if(state.lastDay!==today){const yesterday=new Date(Date.now()-86400000);yesterday.setDate(yesterday.getDate()-1);const y=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,'0')}-${String(yesterday.getDate()).padStart(2,'0')}`;state.streak=state.lastDay===y?state.streak+1:1;state.lastDay=today}if(isNew)state.completed.push(currentLesson.id);const p=PACKS[currentLesson.unit.pack],learnedWords=LESSON_SEQUENCES[currentLesson.unit.pack]?.[currentLesson.index]?.words||p.words;learnedWords.forEach(x=>{if(!state.knownWords.includes(x[0]))state.knownWords.push(x[0])});const unitKey=`${currentLesson.section.id}-${currentLesson.unit.id}`;const unitNowComplete=currentLesson.unit.lessons.every((_,i)=>state.completed.includes(`${unitKey}-${i}`));let milestone=false;if(unitNowComplete&&!state.unitRewards.includes(unitKey)){state.unitRewards.push(unitKey);state.xp+=25;state.questXP+=25;state.gems+=10;reward+=25;gemsEarned+=10;milestone=true}checkQuestReward();const unlockedBadges=checkAchievements();save();updateStats();const next=allLessons().find(x=>unlocked(x)&&!state.completed.includes(x.id));root.innerHTML=`<div class="lesson-screen result-screen"><div class="confetti">✦ ✧ ✦ ✧ ✦</div><div class="result-medal">${perfect?'🏆':'🌟'}</div><span class="eyebrow">${perfect?'PERFECT LESSON':'LESSON COMPLETE'}</span><h1>${perfect?'Savršeno!':'Odlično!'}</h1><p>You showed up for your Croatian. That counts.</p><div class="result-stats"><div><b>+${reward}</b><small>XP earned${milestone?' · unit bonus':''}</small></div><div><b>${accuracy}%</b><small>Accuracy</small></div><div><b>+${gemsEarned}</b><small>Gems</small></div><div><b>🔥 ${state.streak}</b><small>Day streak</small></div></div><div class="result-new"><span>📚</span><div><b>Words in your word garden</b><small>${learnedWords.map(x=>x[0]).join(' · ')}</small></div></div>${milestone?'<div class="new-badge">🎁 Unit milestone unlocked · +25 XP · +10 gems</div>':''}${unlockedBadges.length?`<div class="new-badge">🏅 New badge${unlockedBadges.length>1?'s':''}: ${unlockedBadges.join(', ')}</div>`:''}<div class="result-actions"><button class="secondary-result" id="result-home">Back to path</button>${next?`<button class="primary-result" id="result-next">Next lesson <span>→</span></button>`:''}</div></div>`;document.getElementById('result-home').onclick=()=>{root.innerHTML='';navigate('learn')};document.getElementById('result-next')?.addEventListener('click',()=>{root.innerHTML='';startLesson(next)});}
function checkAchievements(){const known=state.knownWords.length,all=allLessons();const unlock=[];const give=(id,name,yes)=>{if(yes&&!state.achievements.includes(id)){state.achievements.push(id);unlock.push(name)}};give('first','First steps',state.lessonsDone>=1);give('perfect','Perfect!',state.perfect>=1);give('words100','Word collector',known>=100);give('streak7','Week of words',state.streak>=7);give('streak30','One month strong',state.streak>=30);give('words1000','Word wonder',known>=1000);give('unit','Unit explorer',COURSES.some(c=>c.units.some(u=>u.lessons.every((_,i)=>state.completed.includes(`${c.id}-${u.id}-${i}`)))));give('section','Section star',COURSES.some(c=>c.units.every(u=>u.lessons.every((_,i)=>state.completed.includes(`${c.id}-${u.id}-${i}`)))));return unlock}
function startFlashcard(){const words=state.knownWords.length?state.knownWords:PACKS.hello.words.map(x=>x[0]);let i=0,show=false;const showCard=()=>{const hr=words[i%words.length],en=findTranslation(hr);const root=document.getElementById('lesson-root');root.innerHTML=`<div class="lesson-screen mini-game"><header class="lesson-top"><button class="close-lesson" id="mini-close">×</button><div class="exercise-label">WORD GARDEN · ${i+1} / 5</div><span class="mini-gem">✦ ${state.gems}</span></header><div class="flashcard" id="flip-card"><span class="eyebrow">${show?'MEANING':'CROATIAN'}</span><b>${show?esc(en):esc(hr)}</b><small class="flashcard-phonetic">${esc(phoneticText(hr))}</small><small>${show?esc(hr):'Think of the meaning, then tap to reveal'}</small></div><div class="flash-actions"><button class="secondary-result" id="fc-reveal">${show?'I knew it':'Reveal meaning'}</button>${show?'<button class="primary-result" id="fc-next">Got it · +2 XP</button>':''}</div></div>`;document.getElementById('mini-close').onclick=()=>{document.getElementById('lesson-root').innerHTML='';navigate('practice')};document.getElementById('fc-reveal').onclick=()=>{if(!show){show=true;showCard()}else{state.xp+=2;state.reviewed++;state.gems+=1;state.questXP+=2;save();updateStats();i++;show=false;if(i>=5){document.getElementById('lesson-root').innerHTML=`<div class="lesson-screen result-screen"><div class="result-medal">🪴</div><h1>Lovely review!</h1><p>You revisited five words.</p><div class="result-stats"><div><b>+10</b><small>XP</small></div><div><b>+5</b><small>Gems</small></div><div><b>5</b><small>Words reviewed</small></div></div><button class="primary-result result-full" id="review-done">Done</button></div>`;document.getElementById('review-done').onclick=()=>{document.getElementById('lesson-root').innerHTML='';navigate('practice')}}else showCard()}};document.getElementById('fc-next')?.addEventListener('click',()=>document.getElementById('fc-reveal').click())};showCard()}
function startHeartPractice(){
  const root=document.getElementById('lesson-root');
  const starter=LESSON_SEQUENCES.hello[0].words;
  const vocabulary=(state.knownWords.length?state.knownWords.map(word=>[word,findTranslation(word)]).filter(pair=>pair[1]):starter);
  let roundNumber=0,correctCount=0;
  function finish(){state.hearts=Math.min(5,state.hearts+correctCount);state.xp+=correctCount*3;state.gems+=correctCount;state.reviewed+=3;save();updateStats();root.innerHTML=`<div class="lesson-screen result-screen"><div class="result-medal">💗</div><h1>Hearts restored</h1><p>You answered ${correctCount} of 3 review questions correctly.</p><div class="result-stats"><div><b>♥ ${state.hearts}</b><small>Hearts</small></div><div><b>+${correctCount*3}</b><small>XP</small></div><div><b>+${correctCount}</b><small>Gems</small></div></div><button class="primary-result result-full" id="heart-done">Back to practice</button></div>`;document.getElementById('heart-done').onclick=()=>{root.innerHTML='';navigate('practice')}}
  function round(){
    if(roundNumber>=3){finish();return}
    const pair=vocabulary[Math.floor(Math.random()*vocabulary.length)];
    const distractors=shuffle(vocabulary.filter(candidate=>candidate[0]!==pair[0]&&choiceKey(candidate[1])!==choiceKey(pair[1])).map(candidate=>candidate[1]));
    const options=shuffle([pair[1],...distractors.slice(0,2)]);
    root.innerHTML=`<div class="lesson-screen mini-game"><header class="lesson-top"><button class="close-lesson" id="mini-close">×</button><div class="exercise-label">HEART PRACTICE · ${roundNumber+1} / 3</div><span class="lesson-hearts">♥ ${state.hearts}</span></header><div class="question-area"><div class="exercise-label">Review a learned word</div><h2>What does “${esc(pair[0])}” mean?</h2>${pronunciationGuide(pair[0])}<div class="answer-options">${options.map((option,index)=>`<button class="answer-option" data-heart-choice="${index}">${esc(option)}</button>`).join('')}</div><div id="feedback" class="feedback"></div><button id="heart-check" class="check-button" disabled>Check</button></div></div>`;
    document.getElementById('mini-close').onclick=()=>{root.innerHTML='';navigate('practice')};
    let answer='';
    root.querySelectorAll('[data-heart-choice]').forEach(button=>button.onclick=()=>{root.querySelectorAll('.answer-option').forEach(option=>option.classList.remove('selected'));button.classList.add('selected');answer=options[Number(button.dataset.heartChoice)];document.getElementById('heart-check').disabled=false});
    document.getElementById('heart-check').onclick=()=>{const ok=choiceKey(answer)===choiceKey(pair[1]);if(ok)correctCount++;const feedback=document.getElementById('feedback');feedback.className=`feedback ${ok?'good':'bad'}`;feedback.innerHTML=`<b>${ok?'Correct!':'Not quite — here’s the answer.'}</b><strong class="feedback-answer">${esc(pair[0])} = ${esc(pair[1])}</strong><span class="feedback-pronunciation">Say it: <b>${esc(phoneticText(pair[0]))}</b></span><span>${ok?'Nice review.':`You chose “${esc(answer)}.” This word means “${esc(pair[1])}.”`}</span>`;const check=document.getElementById('heart-check');check.textContent='Continue';check.onclick=()=>{roundNumber++;round()}};
  }
  round();
}function startQuickChallenge(){const item=allLessons()[Math.max(0,state.completed.length-1)]||allLessons()[0];const original=makeQuestions(item);quickMode=true;currentLesson=item;currentQuestions=original.slice(0,3);questionIndex=0;lessonCorrect=0;missedQuestions=new Set();renderQuestion();}

document.querySelectorAll('.nav-item,[data-view="profile"],.top-avatar').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));updateStats();renderPath();setInterval(updateStats,60000);
